@startuml

class Driver {
  + driverID : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licensePlate : string
  + isInRepairShop : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : ShiftType
}

class Schedule {
  + date : date
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

Driver "1" -- "*" Schedule
Bus "1" -- "*" Schedule
Route "1" -- "*" Schedule
Schedule "*" -- "1" Shift

@enduml

